<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\AuditService;use App\Services\ImportService;use App\Services\NotificationService;use App\Services\PermissionService;use App\Services\QueueService;use App\Services\ReportService;
final class ManagementController{
 private function guard(string $p):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$p);}
 public function dashboard():void{$this->guard('dashboard.view');$stats=ReportService::dashboard();View::render('management/dashboard',compact('stats'));}
 public function rebuildQueue():void{$this->guard('prices.queue.manage');Security::verifyCsrf();$count=QueueService::rebuild();AuditService::log(Auth::userId(),'queue.rebuild',null,null,null,['count'=>$count]);Security::redirect('/dashboard');}
 public function suppliers():void{$this->guard('suppliers.view');$suppliers=Database::connection()->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();View::render('management/suppliers',compact('suppliers'));}
 public function storeSupplier():void{$this->guard('suppliers.create');Security::verifyCsrf();$s=Database::connection()->prepare('INSERT INTO suppliers(code,name,phone,email,contact_name,notes) VALUES(:c,:n,:p,:e,:cn,:no)');$s->execute(['c'=>trim((string)($_POST['code']??''))?:null,'n'=>trim((string)($_POST['name']??'')),'p'=>trim((string)($_POST['phone']??''))?:null,'e'=>trim((string)($_POST['email']??''))?:null,'cn'=>trim((string)($_POST['contact_name']??''))?:null,'no'=>trim((string)($_POST['notes']??''))?:null]);AuditService::log(Auth::userId(),'supplier.create','supplier',(string)Database::connection()->lastInsertId());Security::redirect('/admin/suppliers');}
 public function notifications():void{$this->guard('notifications.view');$rows=NotificationService::list(Auth::userId());View::render('management/notifications',compact('rows'));}
 public function readNotification(int $id):void{$this->guard('notifications.view');NotificationService::markRead($id,Auth::userId());Security::redirect('/notifications');}
 public function audit():void{$this->guard('audit.view');$rows=Database::connection()->query('SELECT TOP 300 a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC')->fetchAll();View::render('management/audit',compact('rows'));}
 public function reports():void{$this->guard('reports.view');$rows=ReportService::prices();View::render('management/reports',compact('rows'));}
 public function exportPrices():void{$this->guard('reports.export');$rows=ReportService::prices();header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment; filename=pricing-report.csv');echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,['product_code','product_name','unit','latest_date','min_price','max_price','avg_price']);foreach($rows as $r)fputcsv($o,$r);fclose($o);exit;}
 public function settings():void{$this->guard('settings.view');$rows=Database::connection()->query('SELECT * FROM system_settings ORDER BY setting_key')->fetchAll();View::render('management/settings',compact('rows'));}
 public function saveSetting():void{$this->guard('settings.manage');Security::verifyCsrf();$k=trim((string)($_POST['setting_key']??''));$v=(string)($_POST['setting_value']??'');if($k==='')exit('کلید الزامی است.');$pdo=Database::connection();$s=$pdo->prepare('MERGE system_settings AS t USING (SELECT :k setting_key,:v setting_value,:u updated_by) s ON t.setting_key=s.setting_key WHEN MATCHED THEN UPDATE SET setting_value=s.setting_value,updated_by=s.updated_by,updated_at=SYSDATETIME() WHEN NOT MATCHED THEN INSERT(setting_key,setting_value,updated_by) VALUES(s.setting_key,s.setting_value,s.updated_by);');$s->execute(['k'=>$k,'v'=>$v,'u'=>Auth::userId()]);AuditService::log(Auth::userId(),'setting.update','setting',$k,null,$v);Security::redirect('/settings');}
 public function importForm():void{$this->guard('imports.view');View::render('management/import');}
 public function importProducts():void{$this->guard('imports.manage');Security::verifyCsrf();if(empty($_FILES['file']['tmp_name']))exit('فایل انتخاب نشده است.');$result=ImportService::productsCsv($_FILES['file']['tmp_name'],Auth::userId(),$_FILES['file']['name']);View::render('management/import-result',compact('result'));}
}